package counter

import "unicode"

// counter is a correct implementation of the Counter interface.
// It counts the number of lines, letters and total characters
// across all strings added via AddString.
type counter struct {
	newlines, characters, letters int
	lastChar                      rune
}

// NewCounter returns a new Counter.
func NewCounter() Counter {
	return &counter{}
}

func (c *counter) AddString(s string) {
	for _, char := range s {
		c.lastChar = char
		if char == '\n' {
			c.newlines++
		} else if unicode.IsLetter(char) {
			c.letters++
		}
		c.characters++
	}
}

func (c counter) Lines() int {
	switch {
	case c.characters == 0:
		return 0
	case c.lastChar == '\n':
		return c.newlines
	default:
		return c.newlines + 1
	}
}

func (c counter) Letters() int    { return c.letters }
func (c counter) Characters() int { return c.characters }

